function S(e){
    return String(this.java.getString(e))    
}

function getSvg(comment_total) {
   const {java} = this;
   let co;
   //段评气泡颜色[边框,文字]
   let color = ["#B2B2B2","#707070"];
   try{
       co = "#" + String(java.getReadBookConfigMap()["textColor"]).match(/.{6}$/)[0];

    if (String(java.getThemeConfigMap()["isNightTheme"]) === "true") {
        co = "#" + String(java.getReadBookConfigMap()["textColorNight"]).match(/.{6}$/)[0];      
    }
    color = [co, co];     
    }catch(e){}


let svg = `
  <svg width="1000" height="800" xmlns="http://www.w3.org/2000/svg">
    <path d="M865 100 h-600c-60 0-110 50-110 110v150l-120 80 120 80v150c0 60 50 110 110 110h600c60 0 110-50 110-110V210c0-60-50-110-110-110z  " fill="none" stroke="${color[0]}" stroke-width="55"/>
    <text x="570" y="565" font-family="Roboto Condensed" text-anchor="middle" dominant-baseline="middle" font-size="420" font-weight="bold" fill="${color[1]}">
      ${comment_total || "无"}
    </text>
  </svg>
`;
    return "data:image/svg+xml;base64," + java.base64Encode(svg);
}



function getImage(comment_total,postid, blogid,pid){
  return `<img src="data:image/svg+xml;base64,,{"style":"TEXT","type":"lofter","js":"getSvg(${comment_total})","click":"toReview(${comment_total},${postid}, ${blogid}, '${pid}')"}">`;
}

function toReview(comment_total,postid, blogid, pid,t) {
    const {
        java
    } = this;
  let font_size = 13;
  let contentapi,ptext;
  if(t==1){
     contentapi = `https://api.lofter.com/comment/l1/page.json?postId=${postid}&blogId=${blogid}&offset=0&needGift=1&openFansVipPlan=0&dunType=1`;
  }else{
       contentapi = `https://api.lofter.com/comment/pCommentList.json?postId=${postid}&blogId=${blogid}&offset=0&pid=${pid}&imgId=&commentId=`;
  }
  let contentJson = java.ajax(contentapi);
  let jsonData = JSON.parse(contentJson).data.list;
  let currentUrl = contentapi;

  if(t!==1){
  ptext = jsonData[0].quote.replace(/\s*/g,'').replace(/^(.{40}).*/,'$1.......');
  let ytext = jsonData[0].quote;
  ptext = `<div class="p" style="font-size:12px;margin-top:2px;margin-left:12px;display:flex;align-items:center;background:#ffffff;overflow:auto;max-height:80px" onclick="
    const p1 = this.querySelector('.p1');
    const p2 = this.querySelector('.p2');
    if (p1.style.display !== 'none') {
        p1.style.display = 'none';
        p2.style.display = 'block';
        this.style.alignItems = 'flex-start'; 
    } else {
        p1.style.display = 'block';
        p2.style.display = 'none';
        this.style.alignItems = 'center'; 
    }
">
    <p class="p1" style="margin:0;padding:0;">
        <a style="color:#4a89dc;font-weight:bold;">原文：</a>${ptext}
    </p>
    <p class="p2" style="margin-top:3px;padding:0;display:none;">
        <a style="color:#4a89dc;font-weight:bold;">原文：</a>${ytext}
    </p>
</div>
`;
  }else{
      ptext = `<div style="width:100%;display:flex;align-items:center;justify-content:center"><p style="font-size:14px;">${pid}</p></div>`
  }

 let html = `<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css">
    <style>
    :root{--primary-color:#5d9cec;--primary-light:#e6f0fa;--primary-dark:#4a89dc;--accent-color:#ff6b6b;--text-dark:#2d3748;--text-light:#718096;--text-lighter:#a0aec0;--bg-color:#f5f7fa;--card-bg:#ffffff;--border-color:#e8e8e8;--shadow-color:rgba(0,0,0,0.05);}*{margin:0;padding:0;box-sizing:border-box;}body{font-family:'Inter','PingFangSC','MicrosoftYaHei',sans-serif;background-color:var(--bg-color);color:var(--text-dark);line-height:1.6;padding-top:50px;padding-bottom:60px;}/*顶部标签栏*/.tab-bar{position:fixed;top:0;left:0;right:0;background-color:var(--card-bg);display:flex;min-height:50px;height:auto;border-bottom:1px solid var(--border-color);z-index:100;}.p{width:88%;font-weight:bold;background:#ffffff}.comment-item{margin-left:10px;margin-right:10px;background-color:var(--card-bg);border-radius:8px;padding:15px;margin-bottom:15px;box-shadow:0 2px 8px var(--shadow-color);}.comment-header{display:flex;align-items:center;margin-bottom:10px;}.username{font-weight:600;font-size:11px;color:var(--primary-dark);margin-right:10px;}.comment-info{display:flex;justify-content:space-between;}.comment-meta{font-size:10px;color:var(--text-light);margin-top:5px;}.comment-content{font-size:${font_size}px;line-height:1.6;color:var(--text-dark);margin-bottom:10px;}.comment-actions{display:flex;justify-content:flex-end;}.action-btn{display:flex;align-items:center;margin-left:20px;font-size:10px;color:var(--text-light);transition:all0.2s;}.action-btn:hover{color:var(--primary-color);}.action-btni{margin-right:5px;}.replies-section{margin-top:15px;padding-left:15px;border-left:2px solid var(--primary-light);}.reply-item{padding:12px 0;border-bottom:1px dashed var(--border-color);}.reply-item:last-of-type{border-bottom:none;}.reply-header{display:flex;align-items:center;margin-bottom:5px;}.load-more-replies,.close-more-replies{font-size:12px;color:var(--primary-color);text-align:center;padding:10px 0;font-weight:500;}/*悬浮评论按钮*/.floating-btn{position:fixed;bottom:30px;right:15px;width:30px;height:60px;display:flex;align-items:center;justify-content:center;flex-direction:column;font-size:20px;z-index:100;}#top,#down{opacity:0.4}#top:hover,#down:hover{opacity:1}.ef{width:24px;display:inline-block;vertical-align:middle;margin-top:-4px;}.comment-item:first-of-type{margin-top:20px}
    .comment-pic{width:100px;height:auto}
    .comment-pic img{width:100%}
    .comment-quote{font-size:10px;margin-top:5px;background:#eee;border-radius:9px;padding:0px 8px}
    .title{text-align:center;width:100%;font-size:15px;margin:5px;color:#4a89dc}
    .badge {font-size: 10px;padding: 0px 5px;border-radius: 4px;margin-right: 8px;font-weight: 500;color:#77C377;}.load-more-replies,.close-more-replies {font-size: 12px;color: var(--primary-color);text-align: center;padding: 10px 0;font-weight: 500;}
    .hide{display:none}
</style>
</head>

<body>
    <!-- 顶部标签栏 -->
    <div class="tab-bar">
            ${ptext}
    </div>


    <!-- 评论区域 -->
    <div class="comments-container">
            <div style="text-align: center;

        padding: 20px;
        color: #666;
        font-size: 14px;" class="loading">加载中......</div>
    </div>

    <!-- 悬浮按钮 -->
    <div class="floating-btn">
        <div id="top"><i class="fa fa-arrow-circle-up"></i></div>
        <div id="down"><i class="fa fa-arrow-circle-down"></i></div>
    </div>

</body>
</html>
`;

let script = `setTimeout(function() {  
    let currentUrl = \`${currentUrl}\`;
    let contentJson = ${contentJson};
    let isLoading = false;
    let page = 1;
    let hasMore = true;
    loadUrl();

    function loadUrl(){
        let JsonData = getJson(contentJson);
        let html = createCommentHtml(JsonData);
        document.querySelector('.comments-container').innerHTML = html;
        openReply();
        window.scrollTo(0, 0);
    }

function getJson(jsonData,type){
    try{
        if(/^http/.test(jsonData)){
            jsonData = java.ajax(jsonData);
            jsonData = JSON.parse(jsonData || "{}");
        }
        JsonData = jsonData;
         if(type!==0)contentJson = jsonData;
        let data = JsonData?.data ?? {};
        let r = {};
        let commentList = [];
        let list = data.list;
        if(data.hotList && data.hotList.length>0){
            commentList.push({
                "title":"热门评论"
            });
            data.hotList.push({title:"最新评论"});
            list =  data.hotList.concat(list)
        }

        for(i in list){
            let x = list[i];
            let comment = {};
            if(x.title){
                commentList.push(x);
                continue;
            }
            comment.meta = java.timeFormat(x.publishTime)+"•"+(x.ipLocation??"");
            comment.content = x.content;
            comment.quote = (x.quote??"").replace(/^(.{12}).*/,'$1...');
            comment.quote = "${t}"=="1"?comment.quote:"";
            comment.authorFeedBack = x.authorFeedBack;
            comment.author = String(x.publisherBlogInfo.blogId) == "${blogid}"?"作者":"";
            comment.blogId = x.publisherBlogInfo.blogId;
            comment.emotes = x.emotes??[];
            comment.username = x.publisherBlogInfo.blogNickName;
            comment.l2Count = x.l2Count;
            comment.id = x.id;
            comment.agreenum = x.likeCount;
            comment.pics = x.images?x.images.map(x=>{return "<img src=\\""+x.orign+"\\">"}).join(""):"";
        commentList.push(comment)
