function getCode() {
    try {

    	let imgurl = "https://www.lofter.com/lpt/photoCaptcha/getPhotoCaptcha.do?width=270&height=126&" + Date.now();

        //	java.log(imgurl)
        java.toast("请输入图片验证码");
        let code = java.getVerificationCode(imgurl);
        let codeurl = "https://www.lofter.com/lpt/getCaptchaPlus.do," + JSON.stringify({
            "method": "POST",
